export async function initializeLiveAutomationStore(db){await db.batch([
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_previews(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,nonce_hash TEXT NOT NULL,preview_hash TEXT NOT NULL,expires_at TEXT NOT NULL)'),
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_activations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,account_id TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL)'),
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_accounts(owner_id TEXT NOT NULL,account_id TEXT NOT NULL,revision INTEGER NOT NULL,mutation_token TEXT,body TEXT NOT NULL,PRIMARY KEY(owner_id,account_id))'),
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_orders(owner_id TEXT NOT NULL,account_id TEXT NOT NULL,activation_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,identifier TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL,applied_quantity TEXT NOT NULL,applied_fee TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(owner_id,idempotency_key),UNIQUE(owner_id,identifier))'),
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_fills(owner_id TEXT NOT NULL,account_id TEXT NOT NULL,trade_id TEXT NOT NULL,identifier TEXT NOT NULL,body TEXT NOT NULL,PRIMARY KEY(owner_id,account_id,trade_id))'),
 statement(db,'CREATE TABLE IF NOT EXISTS live_automation_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,activation_id TEXT NOT NULL,kind TEXT NOT NULL,recorded_at TEXT NOT NULL,body TEXT NOT NULL)')]);await db.batch([
 statement(db,'CREATE INDEX IF NOT EXISTS live_automation_orders_pending ON live_automation_orders(owner_id,account_id,state)'),
 statement(db,"CREATE UNIQUE INDEX IF NOT EXISTS live_automation_one_active_profile ON live_automation_activations(owner_id,account_id,json_extract(body,'$.config.profileId')) WHERE status='ENABLED'"),
 statement(db,'CREATE INDEX IF NOT EXISTS live_automation_owner_activations ON live_automation_activations(owner_id,status)'),...eventIndexStatements(db)]);}
