 check(['KRW','BTC'].includes(input.quoteCurrency)&&Array.isArray(input.marketIds)&&input.marketIds.length>0&&input.marketIds.length<=500&&new Set(input.marketIds).size===input.marketIds.length&&input.marketIds.every(m=>new RegExp('^'+input.quoteCurrency+'-[A-Z0-9]{1,20}$').test(m)),'LIVE_CONFIG_MARKETS','운용 통화와 종목을 확인하세요.');
