function accountEvent(db,owner,id,kind,body,now,accountId,token){return statement(db,'INSERT INTO live_automation_events(id,owner_id,activation_id,kind,recorded_at,body) SELECT ?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM live_automation_accounts WHERE owner_id=? AND account_id=? AND mutation_token=?)',crypto.randomUUID(),owner,id,kind,now,JSON.stringify(body),owner,accountId,token);}

